fn ose_init(o: &Rc<Obj>, p: &[V]) {
    let n = p.len();
    let mut stored = p.to_vec();
    let mut myerrno: i64 = 0;
    if n >= 2 && n <= 5 {
        myerrno = match &p[0] {
            V::Int(i) => *i,
            V::Bool(b) => *b as i64,
            _ => -1,
        };
