            o.set(sym("filename"), p[2].clone());
            if n >= 5 && !matches!(p[4], V::None) {
                o.set(sym("filename2"), p[4].clone());
            }
            stored = p[..2].to_vec();
        }
    }
    o.set(sym("__ose_myerrno__"), V::Int(myerrno));
    o.set("args", tup(stored));
}
